### LLD Java Domain Model

```java
public interface CRDT<T> {
    T apply(Operation op);
    T getState();
}

public abstract class AbstractCRDT<T> implements CRDT<T> {
    protected T state;
    @Override public T getState() { return state; }
}

public enum OpType { INSERT, DELETE, UPDATE }

public record Operation(OpType type, String key, String value, long lamport) {}

public class GCounter extends AbstractCRDT<Long> {
    public GCounter() { this.state = 0L; }
    @Override public Long apply(Operation op) {
        if (op.type() == OpType.INSERT) state += Long.parseLong(op.value());
        return state;
    }
}
```

