// 1. Merge Intervals
public List<int[]> mergeIntervals(List<int[]> intervals) {
    intervals.sort(Comparator.comparingInt(a -> a[0]));
    List<int[]> res = new ArrayList<>();
    for (int[] iv : intervals) {
        if (res.isEmpty() || res.get(res.size()-1)[1] < iv[0]) res.add(iv);
        else res.get(res.size()-1)[1] = Math.max(res.get(res.size()-1)[1], iv[1]);
    }
    return res;
}

// 2. Longest Increasing Subsequence
public int lengthOfLIS(int[] nums) {
    int[] dp = new int[nums.length];
    int size = 0;
    for (int x : nums) {
        int i = Arrays.binarySearch(dp, 0, size, x);
        if (i < 0) i = -(i + 1);
        dp[i] = x;
        if (i == size) size++;
    }
    return size;
}

// 3. Top‑K Frequent Elements
public List<Integer> topKFrequent(int[] nums, int k) {
    Map<Integer,Integer> freq = new HashMap<>();
    for (int n : nums) freq.merge(n,1,Integer::sum);
    PriorityQueue<Map.Entry<Integer,Integer>> pq = new PriorityQueue<>(Map.Entry.comparingByValue());
    for (var e : freq.entrySet()) {
        pq.offer(e);
        if (pq.size() > k) pq.poll();
    }
    List<Integer> res = new ArrayList<>();
    while (!pq.isEmpty()) res.add(pq.poll().getKey());
    Collections.reverse(res);
    return res;
}
```

