    @PostMapping("/{type}")
    public ResponseEntity<CRDT<?>> create(@PathVariable CRDTType type){
        return ResponseEntity.ok(service.create(type));
    }
    @PutMapping("/{id}/merge")
    public ResponseEntity<CRDT<?>> merge(@PathVariable UUID id, @RequestBody CRDT<?> other){
        return ResponseEntity.ok(service.merge(id, other));
