public interface CRDTOperation<T> {
    UUID getId();
    long getTimestamp();
    T apply(T state);
}

public abstract class AbstractCRDT<T> {
    protected T state;
    public abstract T applyOperation(CRDTOperation<T> op);
}

public class LWWRegister extends AbstractCRDT<String> {
    @Override
    public String applyOperation(CRDTOperation<String> op) {
        if (op.getTimestamp() > stateTimestamp) {
            state = op.apply(state);
            stateTimestamp = op.getTimestamp();
        }
        return state;
    }
}

