public enum OpType { ADD, REMOVE, UPDATE }

public class Counter extends AbstractCrdt<Long> {
    public Counter(UUID id, long timestamp, Long value) { super(id, timestamp, value); }
    @Override
    public Counter merge(Counter other) {
        return new Counter(id, Math.max(timestamp, other.timestamp), Math.max(value, other.value));
    }
